const num = (x: string) => (x === "" ? null : Number(x));

function split(s: string): SplitStats {
  const [n, days, avgNet, avgGross, avgExSpy, hit, t, sharpe, skew, kurt] = s.split(",");
  return { n: Number(n), days: Number(days), avgNet: num(avgNet), avgGross: num(avgGross), avgExSpy: num(avgExSpy), hit: num(hit), t: num(t), sharpe: num(sharpe), skew: Number(skew), kurt: Number(kurt) };
}

const REGIME_ORDER: Regime[] = ["Up, calm", "Up, stressed", "Down, calm", "Down, stressed"];

export interface RealVariantRow {
  partial: VariantPartial;
  /** As stored in production, to compare with what `finalize` gives here. */
  stored: { dsr: number | null; fdr: boolean; passed: boolean };
  live: LiveRecord;
}

export function parseRealVariants(text = REAL_VARIANT_ROWS): RealVariantRow[] {
  return text.trim().split("\n").map((line) => {
    const [key, is, os, rg, maxDrawdown, dsr, fdr, passed, live, years, curve] = line.split("|");
    const r = rg.split(",");
    let cum = 0;
    const partial: VariantPartial = {
      key,
      inSample: split(is),
      outSample: split(os),
      regimes: Object.fromEntries(REGIME_ORDER.map((name, k) => [name, { n: Number(r[2 * k]), avgNet: num(r[2 * k + 1]) }])) as VariantPartial["regimes"],
      years: years.split(";").map((y) => {
        const [year, n, avgNet] = y.split(":");
        return { year, n: Number(n), avgNet: num(avgNet) };
      }),
      curve: curve.split(",").map((p) => {
        const [idx, d] = p.split(":").map(Number);
        cum += d;
        return [`${2016 + Math.floor(idx / 12)}-${String((idx % 12) + 1).padStart(2, "0")}`, cum / 1e4] as [string, number];
      }),
      maxDrawdown: Number(maxDrawdown),
    };
    const [n, avgNet, avgExSpy, hit, since] = live.split(",");
    return { partial, stored: { dsr: num(dsr), fdr: fdr === "t", passed: passed === "t" }, live: { n: Number(n), avgNet: num(avgNet), avgExSpy: num(avgExSpy), hit: num(hit), since: since || null } };
  });
}

/** The 46 variants as the page receives them (the strict gate re-applied with this repo's code). */
export function realVariants(): VariantMeta[] {
  const rows = parseRealVariants();
  const live = new Map(rows.map((r) => [r.partial.key, r.live]));
  return finalize(rows.map((r) => r.partial)).map((p) => variantMeta(p, live.get(p.key)));
}
